class Solution {
public:
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        int n1 = nums1.size(), n2 = nums2.size();
        if (6 * min(n1, n2) < max(n1, n2)) return -1;

        int sum1 = 0, sum2 = 0;
        for (int v : nums1) sum1 += v;
        for (int v : nums2) sum2 += v;

        if (sum1 == sum2) return 0;
        if (sum1 > sum2) {
            swap(nums1, nums2);
            swap(sum1, sum2);
        }

        int diff = sum2 - sum1;
        int freq[6] = {0};
        for (int v : nums1) freq[6 - v]++;
        for (int v : nums2) freq[v - 1]++;

        int ops = 0;
        for (int g = 5; g >= 1 && diff > 0; g--) {
            int take = min(freq[g], (diff + g - 1) / g);
            ops += take;
            diff -= take * g;
        }
        return ops;
    }
};
